CREATE OR REPLACE FUNCTION public.feedback_admin_reply(p_issue_id uuid, p_content text, p_images text[] DEFAULT '{}'::text[], p_next_status text DEFAULT NULL::text)
 RETURNS admin_issues
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  actor_email text := coalesce((select auth.jwt() ->> 'email'), 'admin');
  result public.admin_issues;
begin
  if (select auth.uid()) is null or not (select private.is_admin()) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  if not exists (select 1 from public.admin_issues where id = p_issue_id) then
    raise exception 'issue_not_found' using errcode = 'P0002';
  end if;

  if char_length(trim(coalesce(p_content, ''))) = 0
     and cardinality(coalesce(p_images, '{}'::text[])) = 0 then
    raise exception 'reply_required' using errcode = '22023';
  end if;

  if cardinality(coalesce(p_images, '{}'::text[])) > 3 then
    raise exception 'too_many_images' using errcode = '22023';
  end if;

  if p_next_status is not null
     and p_next_status not in ('open', 'in_progress', 'resolved', 'wontfix', 'duplicate') then
    raise exception 'invalid_status' using errcode = '22023';
  end if;

  insert into public.admin_issue_comments(
    issue_id, content, images, created_by, is_admin, kind, metadata
  ) values (
    p_issue_id,
    trim(coalesce(p_content, '')),
    coalesce(p_images, '{}'::text[]),
    actor_email,
    true,
    'comment',
    '{}'::jsonb
  );

  if p_next_status is not null then
    update public.admin_issues
    set status = p_next_status
    where id = p_issue_id;
  end if;

  perform public.feedback_mark_read(p_issue_id);

  select * into result from public.admin_issues where id = p_issue_id;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_mark_read(p_issue_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
begin
  if (select auth.uid()) is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not (
    (select private.is_admin())
    or exists (
      select 1 from public.admin_issues issue
      where issue.id = p_issue_id
        and issue.source = 'user_feedback'
        and lower(issue.created_by) = lower(coalesce((select auth.jwt() ->> 'email'), ''))
    )
  ) then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  insert into public.admin_issue_reads(issue_id, user_id, last_read_at)
  values (p_issue_id, (select auth.uid()), now())
  on conflict (issue_id, user_id)
  do update set last_read_at = excluded.last_read_at;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_prepare_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  actor_email text := coalesce((select auth.jwt() ->> 'email'), 'system');
begin
  if new.status is distinct from old.status then
    if new.status = 'resolved' then
      new.resolved_at := coalesce(new.resolved_at, now());
      if coalesce(new.resolved_by, '') = '' then
        new.resolved_by := actor_email;
      end if;
    elsif old.status = 'resolved' then
      new.resolved_at := null;
      new.resolved_by := '';
      if new.status = 'open' then
        new.reopened_at := now();
      end if;
    end if;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_record_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  actor_email text := coalesce((select auth.jwt() ->> 'email'), nullif(new.resolved_by, ''), 'system');
  actor_is_admin boolean := coalesce((select private.is_admin()), false);
begin
  if new.status is distinct from old.status then
    insert into public.admin_issue_comments (
      issue_id, content, images, created_by, is_admin, kind, metadata
    ) values (
      new.id,
      '',
      '{}'::text[],
      actor_email,
      actor_is_admin,
      'status_change',
      jsonb_build_object('from', old.status, 'to', new.status)
    );
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.feedback_reopen(p_issue_id uuid, p_message text DEFAULT ''::text)
 RETURNS admin_issues
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'private', 'pg_temp'
AS $function$
declare
  actor_email text := coalesce((select auth.jwt() ->> 'email'), '');
  result public.admin_issues;
begin
  if (select auth.uid()) is null then
    raise exception 'unauthenticated' using errcode = '42501';
  end if;

  if not exists (
    select 1 from public.admin_issues issue
    where issue.id = p_issue_id
      and issue.source = 'user_feedback'
      and lower(issue.created_by) = lower(actor_email)
      and issue.status = 'resolved'
  ) then
    raise exception 'feedback_not_reopenable' using errcode = '42501';
  end if;

  if char_length(trim(coalesce(p_message, ''))) > 0 then
    insert into public.admin_issue_comments(
      issue_id, content, images, created_by, is_admin, kind, metadata
    ) values (
      p_issue_id,
      trim(p_message),
      '{}'::text[],
      actor_email,
      false,
      'comment',
      '{}'::jsonb
    );
  end if;

  update public.admin_issues
  set status = 'open'
  where id = p_issue_id;

  perform public.feedback_mark_read(p_issue_id);

  select * into result from public.admin_issues where id = p_issue_id;
  return result;
end;
$function$

CREATE OR REPLACE FUNCTION private.audit_lease_transaction_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_old jsonb;
  v_new jsonb;
  v_changed jsonb;
  v_user_id text;
begin
  v_old := to_jsonb(old) - 'updated_at';
  v_new := to_jsonb(new) - 'updated_at';

  if v_old = v_new then
    return new;
  end if;

  select coalesce((select auth.uid())::text, 'system')
    into v_user_id;

  select coalesce(
    jsonb_object_agg(
      field_key,
      jsonb_build_object('old', v_old -> field_key, 'new', v_new -> field_key)
    ),
    '{}'::jsonb
  )
  into v_changed
  from (
    select field_key
    from jsonb_object_keys(v_old) as old_keys(field_key)
    union
    select field_key
    from jsonb_object_keys(v_new) as new_keys(field_key)
  ) changed_keys
  where (v_old -> field_key) is distinct from (v_new -> field_key);

  insert into public.audit_logs (
    user_id,
    action_type,
    details,
    request_source,
    module,
    target_table,
    target_id,
    target_name,
    old_values,
    new_values,
    event_id,
    occurred_at
  )
  values (
    v_user_id,
    'LEASE_TRANSACTION_UPDATE',
    jsonb_build_object(
      'table', 'lease_transactions',
      'operation', 'UPDATE',
      'changed_fields', v_changed,
      'change_count', (select count(*) from pg_catalog.jsonb_object_keys(v_changed))
    ),
    'database_trigger',
    'lease-submission',
    'lease_transactions',
    new.id::text,
    concat_ws(' · ', nullif(new.company, ''), nullif(new.new_building, '')),
    v_old,
    v_new,
    gen_random_uuid()::text,
    now()
  );

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION private.fill_update_draft_identity_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.user_id is null then
    new.user_id := auth.uid();
  end if;
  if new.record_year is null then
    new.record_year := private.current_submission_year();
  end if;
  if new.record_quarter is null then
    new.record_quarter := private.current_submission_quarter();
  end if;
  return new;
end;
$function$
